#creates the n-sunlet and computes the vanishing ideal of the CFN model based on this network.
#n should be at least 3

function draw_n_sunlet(n::Int64)

    edges = vcat([[i, i+1] for i in 2:n-1], [[2,1],[n,1]], [[i,i+n] for i in 1:n])

    println(edges)

    N = graph_from_edges(Directed, edges)

    return N
end

N = draw_n_sunlet(4)
net = phylogenetic_network(N)
PM = cavender_farris_neyman_model(net)
phi = parametrization(PM)
H = components_of_kernel(2, phi, show_progress = true)
I = ideal(reduce(vcat, collect(values(H))))

